#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        ll L, P;
        int M;
        cin >> L >> M >> P;

        vector<pair<ll, ll>> traps(M);   // {位置, 拆除时间}
        for (int i = 0; i < M; ++i) {
            cin >> traps[i].first;
        }
        for (int i = 0; i < M; ++i) {
            cin >> traps[i].second;
        }

        // 按陷阱位置排序
        sort(traps.begin(), traps.end());

        ll chaser = 1;      // 追捕者坐标
        ll agent = P;       // 小C坐标
        bool escaped = true;

        for (auto &[pos, t] : traps) {
            if (pos >= agent) {          // 只处理前方的陷阱
                chaser += (pos - agent) + t;
                if (chaser >= pos) {     // 在陷阱处被追上
                    escaped = false;
                    break;
                }
                agent = pos;
            }
        }

        if (escaped) {
            chaser += (L - agent);
            if (chaser >= L) {
                escaped = false;
            }
        }

        cout << (escaped ? "YES" : "NO") << "\n";
    }

    return 0;
}
